pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // If post_residual is 0, this is a perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave room for common item sizes
    // Modulo arithmetic to identify "clean" remainders that allow future items to fit.
    let remainder_mod = (post_residual % 25) as f64;
    score += remainder_mod * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Further discount if the combination is highly efficient (near capacity)
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we have very few open bins (avoiding fragmentation early).
        if mean_residual < 20.0 && open_bins_count > 2 {
            score += 40.0; 
        } else {
            score += 10.0;
        }
    }

    // 5. Scarcity/Fitting Logic:
    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

