pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    if is_new_bin {
        // Penalty for opening a new bin: force usage of existing bins unless they are extremely poor fits
        score = 15.0 + (progress * 20.0);
    } else {
        // Reward filling bins tightly: Best Fit Decreasing logic
        // Penalize leaving very small gaps (e.g., 1-5) that are hard to fill later
        if post_residual > 0 && post_residual < 6 {
            score += 40.0;
        }

        // Lookahead heuristic: if next_item_size is large, avoid creating a residual too small for it
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }

        // Global state consideration: if we have many bins, be more aggressive at packing
        // If fitting_bins_count is 1, this is the only bin that can take the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Adjust based on the mean residual to keep bins balanced
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: 
    // Scale the penalty by progress to be more conservative as the stream nears the end.
    // If we are early in the stream, we are more willing to open a new bin if the fit is poor.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.5 - progress);
    }

    // Interaction term: Penalize small residuals that are likely to become "dead space".
    // If post_residual is < 10, it's often a waste unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it.
    if next_item_size > 0 && post_residual < next_item_size && !is_new_bin {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Favor bins that are closer to the mean residual to keep bin fill levels balanced.
    // This helps in keeping the remaining space uniform across bins.
    let dev_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // Final adjustment: if this is the only bin that fits, heavily favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a 'fragment' (small unusable space)
    // Residuals < 10 are often dead space, penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals
    // to accommodate it, otherwise favor filling the bin as tightly as possible.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // This bin cannot fit the next item; penalize based on how much it fails
            // and how many other bins are available to take the load.
            score += (next_item_size - post_residual) as f64 * (1.0 + 1.0 / (fitting_bins_count as f64 + 1.0));
        } else {
            // This bin CAN fit the next item; reward it inversely to remaining space
            score -= (100.0 - post_residual as f64) * 0.5;
        }
    }

    // Global state awareness:
    // If we have many open bins, prioritize closing them (lower post_residual).
    // If we have few, be more conservative to avoid opening new ones.
    if open_bins_count > 0 {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Heuristic for opening a new bin:
    // Only open a new bin if the best fitting bin creates a very small, unusable fragment.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high to discourage it.
        score = 45.0 + (progress * 10.0);

        // If fitting_bins_count is low, we might be forced to open a new bin.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize the post_residual, but prioritize tight fits.
    // A post_residual of 0 is ideal (perfect fit).

    // 2. Harmonic/Modulo behavior:
    // If we have a next item, we want to ensure the post_residual can accommodate it.
    // Penalize if post_residual is slightly too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 150.0; // Heavy penalty for blocking future fit
        } else {
            // Reward if the residual is a good "multiple" for future packing
            score -= (post_residual % next_item_size) as f64 * 0.5;
        }
    }

    // 3. Last Chance Heuristic:
    // If this is the only bin that fits, we are forced to take it unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 40.0; 
    }

    // 4. New Bin Threshold:
    // Only open a new bin if the current best existing bin is truly inefficient.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost + pressure from current open bins
        score = 65.0 + (open_bins_count as f64 * 0.1);
    } else {
        // Favor bins that keep the mean_residual high (consolidating space)
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression scaling:
    // As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= 10.0; // Aggressive packing at the end
    }

    score
}
